import type { Tools } from "../generated/tools";
import { isAuthChange } from "@flows/lib";

/** True when any of the changed files touches authentication or permissions. */
function hasAuthChange(files: File[]): boolean {
  return files.some((file) => isAuthChange(file));
}

export default async function flow(
  input: { repo: string },
  tools: Tools
) {
  const newPullRequests = await tools.github.getNewPRs({ repo: input.repo });

  for (const pr of newPullRequests) {
    const changedFiles = await tools.github.getFiles({ pr });

    if (hasAuthChange(changedFiles)) {
      await tools.slack.send({
        channel: "#security",
        message: `Authentication-related pull request opened in ${input.repo}: ${pr.title}`,
      });
    }
  }
}

import type { Tools } from "../generated/tools";

export default async function flow(
  input: { issueKey: string },
  tools: Tools
) {
  const maxAttempts = 3;
  let issue: Issue | null = null;
  let attempt = 1;

  while (attempt <= maxAttempts && issue === null) {
    try {
      const fetched = await tools.jira.getIssue({ key: input.issueKey });
      issue = fetched;
    } catch {
      // Issue service is flaky — fall through and retry on the next attempt.
    }
    attempt += 1;
  }

  if (issue === null) {
    await tools.slack.send({
      channel: "#ops",
      message: `Could not fetch Jira issue ${input.issueKey} after ${maxAttempts} attempts. Giving up.`,
    });
    return;
  }

  await tools.jira.transitionIssue({ key: issue.key, status: "In Review" });

  return issue;
}

import type { Tools } from "../generated/tools";
import { formatDigest } from "@flows/lib";

export default async function flow(
  input: { repo: string; jql: string; recipient: string },
  tools: Tools
) {
  const [stats, issues, activity] = await Promise.all([
    tools.github.getRepoStats({ repo: input.repo }),
    tools.jira.searchIssues({ jql: input.jql }),
    tools.slack.getChannelActivity({ channel: "#engineering" }),
  ]);

  const digest = formatDigest(stats, issues, activity);

  await tools.email.send({
    to: input.recipient,
    subject: `Weekly digest for ${input.repo}`,
    body: digest,
  });
}

import { severityOf } from "@flows/lib";
import type { Tools } from "../generated/tools";

export default async function flow(
  input: { key: string },
  tools: Tools
) {
  let severity = "unknown";

  try {
    const issue = await tools.jira.getIssue({ key: input.key });
    const classified = severityOf(issue);
    severity = classified;
  } catch {
    // Issue service unavailable — stop early with no notifications.
    return "unavailable";
  }

  if (severity === "critical") {
    const followUp = await tools.jira.createIssue({
      project: "OPS",
      summary: `Follow-up for ${input.key}`,
      description: `Automatically created because ${input.key} was classified as critical.`,
    });
    await tools.slack.send({
      channel: "#incidents",
      message: `Critical issue ${input.key}: follow-up ${followUp.key} created in OPS.`,
    });
  } else if (severity === "high") {
    await tools.slack.send({
      channel: "#engineering",
      message: `High-severity issue ${input.key} needs attention.`,
    });
  }

  return severity;
}

import type { Tools } from "../generated/tools";

export default async function flow(
  input: {
    /** The release note text to publish. */
    releaseNote: string;
    /** Email address of the on-call engineer. */
    onCallAddress: string;
  },
  tools: Tools
) {
  let delivered = false;

  try {
    await tools.slack.send({
      channel: "#releases",
      message: input.releaseNote,
    });
    delivered = true;
  } catch (sendError) {
    try {
      await tools.email.send({
        to: input.onCallAddress,
        subject: "Alert: release note failed to publish",
        body: `Posting the release note to #releases failed: ${String(sendError)}`,
      });
    } catch (alertError) {
      // The on-call alert also failed; the audit line below still records the outcome.
    }
  }

  const auditLine = delivered
    ? "Release note published to #releases successfully."
    : "Release note FAILED to publish to #releases; on-call alerted by email.";

  await tools.slack.send({
    channel: "#audit",
    message: auditLine,
  });

  return { delivered, auditLine };
}

import type { Tools } from "../generated/tools";

function isWip(title: string): boolean {
  return title.startsWith("WIP");
}

export default async function flow(
  input: { repo: string },
  tools: Tools
) {
  const maxComments = 5;

  const pullRequests = await tools.github.getNewPRs({ repo: input.repo });

  let commentsPosted = 0;

  for (const pr of pullRequests) {
    if (isWip(pr.title)) {
      continue;
    }

    if (commentsPosted >= maxComments) {
      break;
    }

    await tools.github.addComment({
      pr,
      body: "This pull request is queued for review.",
    });

    commentsPosted += 1;
  }

  return { commentsPosted };
}
